        SCORE_GAP_TRAILING
    } else {
        SCORE_GAP_INNER
    };
    let mut prev_M: score_t = -::core::f32::INFINITY as score_t;
    let mut prev_D: score_t = -::core::f32::INFINITY as score_t;

