            prev_D = last_d;
            prev_M = last_m;
            *curr_d = score;
            prev_score = if score > prev_score + gap_score {
                score
            } else {
                prev_score + gap_score
            };
            *curr_m = prev_score;
        } else {
            prev_D = last_d;
            prev_M = last_m;
            *curr_d = -::core::f32::INFINITY as score_t;
            prev_score = prev_score + gap_score;
            *curr_m = prev_score;
        }
